import * as THREE from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Apply scene transforms from config
  const scenePos = config.scenePosition || {};
  group.position.set(scenePos.x ?? 0, scenePos.y ?? 0, scenePos.z ?? 0);

  if (scenePos.rotationXYZ) {
    group.rotation.set(
      scenePos.rotationXYZ[0] ?? 0,
      scenePos.rotationXYZ[1] ?? 0,
      scenePos.rotationXYZ[2] ?? 0
    );
  }

  if (scenePos.scaleXYZ) {
    group.scale.set(
      scenePos.scaleXYZ[0] ?? 1,
      scenePos.scaleXYZ[1] ?? 1,
      scenePos.scaleXYZ[2] ?? 1
    );
  }

  // Create plane geometry for card background
  const planeGeometry = new THREE.PlaneGeometry(1, 1);

  // Load texture via cached texture loader
  const texture = ctx.textureLoader.load(config.imageUrl);
  texture.colorSpace = THREE.SRGBColorSpace;

  // Create material (static composition, no lighting effects)
  const material = new THREE.MeshBasicMaterial({
    map: texture,
    side: THREE.DoubleSide,
    transparent: true,
  });

  // Create and add plane mesh
  const planeMesh = new THREE.Mesh(planeGeometry, material);
  group.add(planeMesh);

  // Render text content via MSDF font atlas
  if (config.textContent && config.textContent.length > 0) {
    const textContent = config.textContent[0];
    const textMesh = ctx.fontAtlas.createText(textContent.text, {
      fontSize: 0.34, // headline size from type scale
      fontWeight: textContent.fontWeight ?? 400,
      color: 0x16161d, // ink from Nova Atelier palette
      align: 'center',
    });
    textMesh.position.z = 0.1; // layer above plane
    group.add(textMesh);
  }

  // Resource cleanup
  group.userData.cleanup = () => {
    planeGeometry.dispose();
    material.dispose();
    if (texture) texture.dispose();
  };

  // Event handlers (empty for static card)
  group.userData.handlers = {};

  return group;
}
